import assert from 'node:assert/strict'
import {createServiceLeader} from './leader'
import {serviceDefinition, type Booking, type LockCommand} from './service'
import {LOCK_UNLOCK_TTL_MS, lockCommandExpiresAt, lockCommandIsCurrent} from './lock-policy'
import {runCheck} from './run-check'

async function main() {
    const now = Date.now()
    const midnight = Date.parse(new Date(now).toISOString().slice(0, 10))
    function day(offset: number) { return new Date(midnight + offset * 86_400_000).toISOString().slice(0, 10) }
    function booking(id: string, from: number, to: number): Booking {
        return {id, apartmentId: 'loft-1', guest: 'bob', from: day(from), to: day(to), nights: to - from,
            total: 120, state: 'paid', paymentId: 'pay-' + id, code: '123456', codeArmed: false, ts: now}
    }
    function command(id: string, kind: LockCommand['kind'], bookingId: string, ts = now): LockCommand {
        return {id, kind, bookingId, requestedBy: kind == 'unlock' ? 'bob' : 'system', state: 'pending', ts,
            ...(kind == 'setCode' ? {code: '123456'} : {})}
    }
    const legacyUnlock = {kind: 'unlock' as const, ts: now}
    assert.equal(lockCommandExpiresAt(legacyUnlock), now + LOCK_UNLOCK_TTL_MS)
    assert.equal(lockCommandIsCurrent(legacyUnlock, now + LOCK_UNLOCK_TTL_MS - 1), true)
    assert.equal(lockCommandIsCurrent(legacyUnlock, now + LOCK_UNLOCK_TTL_MS), false)
    assert.equal(lockCommandExpiresAt({...legacyUnlock, expiresAt: now + 120_000}), now + LOCK_UNLOCK_TTL_MS)
    assert.equal(lockCommandIsCurrent({...legacyUnlock, expiresAt: NaN}, now), false)
    assert.equal(lockCommandIsCurrent({...legacyUnlock, expiresAt: Infinity}, now), false)
    assert.equal(lockCommandIsCurrent({kind: 'setCode', ts: now}, now), false, 'unbounded legacy provisioning must obtain a server deadline')
    assert.equal(lockCommandIsCurrent({kind: 'clearCode', ts: now - 300_000}, now), true)
    const initial = structuredClone(serviceDefinition.initial)
    initial.bookings = {
        expired: booking('expired', -3, -1),
        active: booking('active', -1, 1),
        future: {...booking('future', 2, 3), code: '234567'},
        cancelled: {...booking('cancelled', -1, 1), state: 'cancelled'},
        foreign: {...booking('foreign', -1, 1), apartmentId: 'loft-other'},
    }
    initial.locks['lock-1'].commands = {
        expiredStay: command('expiredStay', 'unlock', 'expired'),
        staleUnlock: command('staleUnlock', 'unlock', 'active', now - 60_001),
        validUnlock: command('validUnlock', 'unlock', 'active'),
        futureSet: {...command('futureSet', 'setCode', 'future'), code: '234567'},
        futureUnlock: command('futureUnlock', 'unlock', 'future'),
        expiredExplicit: {...command('expiredExplicit', 'unlock', 'active'), expiresAt: now - 1},
        wrongCode: {...command('wrongCode', 'setCode', 'active'), code: '654321'},
        expiredSet: command('expiredSet', 'setCode', 'expired'),
        cancelledSet: command('cancelledSet', 'setCode', 'cancelled'),
        orphan: command('orphan', 'unlock', 'missing'),
        foreign: command('foreign', 'setCode', 'foreign'),
        wrongGuest: {...command('wrongGuest', 'unlock', 'active'), requestedBy: 'anna'},
        clear: command('clear', 'clearCode', 'expired', now - 300_000),
    }
    const leader = createServiceLeader({definition: {...serviceDefinition, initial}, selfUrl: () => 'http://localhost', log: () => {}})
    try {
        const view = leader.access.snapshot('myLock', {account: 'lock-1', roles: ['device']}) as {
            commands: Record<string, LockCommand>, codes: Record<string, unknown>
        }
        assert.equal(view.commands.expiredStay, undefined, 'an offline unlock cannot outlive its booking')
        assert.deepEqual(Object.keys(view.commands).sort(), ['clear', 'futureSet', 'validUnlock'])
        assert.equal(view.commands.futureSet.kind, 'setCode', 'future stays may provision codes before arrival')
        assert.equal(view.commands.futureSet.expiresAt, Date.parse(day(3)))
        assert.equal(view.commands.validUnlock.expiresAt, now + LOCK_UNLOCK_TTL_MS)
        assert.equal(view.codes['234567'], undefined, 'provisioning a future code does not make it valid today')
        assert.equal(leader.view.state().locks['lock-1'].commands.expiredStay.state, 'pending', 'projection expiry does not invent a physical outcome')
        const board = leader.access.snapshot('hostBoard', {account: 'anna', roles: ['host']}) as {
            apartments: Record<string, {lock: {pending: number, unavailable: number}}>
        }
        const pending = Object.keys(initial.locks['lock-1'].commands).length
        assert.equal(board.apartments['loft-1'].lock.pending, pending, 'pending counts commands without an outcome')
        assert.equal(board.apartments['loft-1'].lock.unavailable, pending - 3, 'the host sees which pending commands cannot execute now')
        assert.throws(() => leader.access.snapshot('myLock', {account: 'anna', roles: ['host']}), /forbidden/)
        await assert.rejects(leader.corridor.execute('anna', 'unlock', 'host-attempt', {bookingId: 'active'}), /forbidden/)
        await leader.corridor.execute('anna', 'addApartment', 'another-lock', {
            id: 'loft-2', title: 'Another loft', pricePerNight: 90, lockId: 'lock-2', devicePassword: 'lock-2-pass',
        })
        await assert.rejects(leader.corridor.execute('lock-2', 'lockReport', 'foreign-report', {commandId: 'validUnlock', ok: true}), /unknown command/)
        await leader.corridor.execute('lock-1', 'lockReport', 'late-report', {commandId: 'staleUnlock', ok: true, detail: 'executed before disconnect'})
        assert.equal(leader.view.state().locks['lock-1'].commands.staleUnlock.state, 'done', 'a delayed report remains a truthful outcome')
        const issued = await leader.corridor.execute('bob', 'unlock', 'new-unlock', {bookingId: 'active'})
        const persisted = leader.view.state().locks['lock-1'].commands[issued.commandId]
        assert.equal(typeof persisted.expiresAt, 'number', 'new unlocks persist a deadline before delivery')
        assert(persisted.expiresAt! <= persisted.ts + LOCK_UNLOCK_TTL_MS)
        assert(persisted.expiresAt! <= Date.parse(initial.bookings.active.to))
        console.log('PASS apartments lock expiry policy: offline restore, valid provisioning, scoped commands and late reports')
    } finally { leader.control.close() }
}

runCheck(main)


